var mod *WasmModule

type CallbackFunc[T any] struct {
	cb     T
	funcID uint64
}

func CreateCallbackFunc[T any](cb T, funcID uint64) *CallbackFunc[T] {
	return &CallbackFunc[T]{
		cb:     cb,
		funcID: funcID,
	}
}

