func (m *WasmModule) toString(ctx context.Context, p uint64) (string, error) {
	if p == 0 {
		return "", nil
	}
	dataAddr, err := m.readU32(p)
	if err != nil {
		return "", err
	}
	length, err := m.readU32(p + 4)
	if err != nil {
		return "", err
	}
	if length == 0 {
		return "", nil
	}
	bytes, err := m.read(dataAddr, length)
	if err != nil {
		return "", err
	}
	return string(bytes), nil
}

